import "server-only";
import { after } from "next/server";
import { getDb } from "./db";
import { processMailBatch } from "./mail";

export function scheduleAccountMail(messageId: string | undefined) {
  if (process.env.ACCOUNT_MAIL_AUTOMATION !== "true") return;
  // Called for known/unknown/cooldown requests alike; no internal ID is serialized.
  // Only the committed message generated by this request can be claimed here.
  after(async () => {
    if (!messageId) return;
    try {
      const result = await processMailBatch(getDb(), 1, { accountOnly: true, messageId });
      const event = JSON.stringify({ event: "account_mail_dispatch", source: "request", ...result });
      try { if (result.retried || result.failed) console.error(event); else console.info(event); } catch { /* Logs cannot change delivery. */ }
    } catch {
      // Preserve the encrypted queue/lease for recovery; never log exceptions or IDs.
      try { console.error(JSON.stringify({ event: "account_mail_dispatch", source: "request", failure: "dispatch_failed" })); } catch { /* No raw errors. */ }
    }
  });
}
